CREATE TABLE IF NOT EXISTS geo_regions (
    id INTEGER PRIMARY KEY,
    name VARCHAR(140) NOT NULL UNIQUE,
    sort_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS geo_cities (
    id BIGINT PRIMARY KEY,
    region_id INTEGER NOT NULL REFERENCES geo_regions(id) ON DELETE CASCADE,
    name VARCHAR(140) NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    UNIQUE(region_id, name)
);

CREATE TABLE IF NOT EXISTS geo_communes (
    id BIGINT PRIMARY KEY,
    region_id INTEGER NOT NULL REFERENCES geo_regions(id) ON DELETE CASCADE,
    city_id BIGINT NOT NULL REFERENCES geo_cities(id) ON DELETE CASCADE,
    name VARCHAR(140) NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    UNIQUE(region_id, name)
);

CREATE INDEX IF NOT EXISTS idx_geo_cities_region_name ON geo_cities(region_id, name);
CREATE INDEX IF NOT EXISTS idx_geo_communes_city_name ON geo_communes(city_id, name);
CREATE INDEX IF NOT EXISTS idx_geo_communes_region_name ON geo_communes(region_id, name);




ALTER TABLE customer_addresses
    ADD COLUMN IF NOT EXISTS region_id INTEGER,
    ADD COLUMN IF NOT EXISTS city_id BIGINT,
    ADD COLUMN IF NOT EXISTS commune_id BIGINT;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_customer_addresses_region') THEN
        ALTER TABLE customer_addresses ADD CONSTRAINT fk_customer_addresses_region FOREIGN KEY (region_id) REFERENCES geo_regions(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_customer_addresses_city') THEN
        ALTER TABLE customer_addresses ADD CONSTRAINT fk_customer_addresses_city FOREIGN KEY (city_id) REFERENCES geo_cities(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_customer_addresses_commune') THEN
        ALTER TABLE customer_addresses ADD CONSTRAINT fk_customer_addresses_commune FOREIGN KEY (commune_id) REFERENCES geo_communes(id);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_customer_addresses_region ON customer_addresses(region_id);
CREATE INDEX IF NOT EXISTS idx_customer_addresses_city ON customer_addresses(city_id);
CREATE INDEX IF NOT EXISTS idx_customer_addresses_commune ON customer_addresses(commune_id);

UPDATE customer_addresses ca
SET
    region_id = gr.id,
    city_id = gc.id,
    commune_id = gco.id
FROM geo_regions gr
JOIN geo_cities gc ON gc.region_id = gr.id
JOIN geo_communes gco ON gco.city_id = gc.id AND gco.region_id = gr.id
WHERE ca.region_id IS NULL
  AND lower(trim(ca.region)) = lower(trim(gr.name))
  AND lower(trim(ca.city)) = lower(trim(gc.name))
  AND lower(trim(ca.comuna)) = lower(trim(gco.name));
